create table public.feed_posts (id uuid primary key default gen_random_uuid(),professional_id uuid not null references public.professional_profiles(id) on delete cascade,interest_id uuid not null references public.interests(id) on delete restrict,image_url text not null check(image_url ~ '^https?://'),caption text not null check(char_length(caption) between 1 and 500),price_from numeric(10,2) check(price_from>=0),aspect_ratio numeric(5,3) not null default .82 check(aspect_ratio between .4 and 2),rating numeric(2,1) not null default 0 check(rating between 0 and 5),rating_count integer not null default 0 check(rating_count>=0),is_published boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.feed_post_likes(post_id uuid references public.feed_posts(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.feed_post_saves(post_id uuid references public.feed_posts(id) on delete cascade,user_id uuid references public.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.feed_post_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.feed_posts(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,body text not null check(char_length(body) between 1 and 1000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index feed_posts_rank_idx on public.feed_posts(is_published,interest_id,rating desc,created_at desc); create index feed_post_comments_post_idx on public.feed_post_comments(post_id,created_at);
alter table public.feed_posts enable row level security; alter table public.feed_post_likes enable row level security; alter table public.feed_post_saves enable row level security; alter table public.feed_post_comments enable row level security;
create policy "published feed is public" on public.feed_posts for select to anon,authenticated using(is_published); create policy "professionals manage own feed posts" on public.feed_posts for all to authenticated using(exists(select 1 from public.professional_profiles p where p.id=professional_id and p.user_id=(select auth.uid()))) with check(exists(select 1 from public.professional_profiles p where p.id=professional_id and p.user_id=(select auth.uid())));
create policy "likes are readable" on public.feed_post_likes for select to anon,authenticated using(true); create policy "users manage own likes" on public.feed_post_likes for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid())); create policy "users manage own saves" on public.feed_post_saves for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "comments are readable" on public.feed_post_comments for select to anon,authenticated using(true); create policy "users create comments" on public.feed_post_comments for insert to authenticated with check(user_id=(select auth.uid())); create policy "users update own comments" on public.feed_post_comments for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid())); create policy "users delete own comments" on public.feed_post_comments for delete to authenticated using(user_id=(select auth.uid()));
grant select on public.feed_posts,public.feed_post_likes,public.feed_post_comments to anon,authenticated; grant insert,update,delete on public.feed_posts,public.feed_post_likes,public.feed_post_saves,public.feed_post_comments to authenticated; grant select on public.feed_post_saves to authenticated;
create trigger feed_posts_set_updated_at before update on public.feed_posts for each row execute function public.set_updated_at(); create trigger feed_comments_set_updated_at before update on public.feed_post_comments for each row execute function public.set_updated_at();
create or replace function public.get_personalized_feed(page_number integer default 0,page_size integer default 10) returns table(id uuid,professional_id uuid,professional_name text,avatar_url text,image_url text,caption text,category text,location text,price_from numeric,rating numeric,rating_count integer,is_verified boolean,like_count bigint,comment_count bigint,is_liked boolean,is_saved boolean,aspect_ratio numeric,created_at timestamptz) language sql stable security invoker set search_path='' as $$
select fp.id,p.id,coalesce(p.display_name,p.business_name),p.profile_photo_url,fp.image_url,fp.caption,i.name,coalesce(p.location,p.business_address),fp.price_from,fp.rating,fp.rating_count,p.is_verified,(select count(*) from public.feed_post_likes l where l.post_id=fp.id),(select count(*) from public.feed_post_comments c where c.post_id=fp.id),exists(select 1 from public.feed_post_likes l where l.post_id=fp.id and l.user_id=(select auth.uid())),exists(select 1 from public.feed_post_saves s where s.post_id=fp.id and s.user_id=(select auth.uid())),fp.aspect_ratio,fp.created_at from public.feed_posts fp join public.professional_profiles p on p.id=fp.professional_id join public.interests i on i.id=fp.interest_id where fp.is_published order by exists(select 1 from public.user_interests ui where ui.user_id=(select auth.uid()) and ui.interest_id=fp.interest_id) desc,fp.rating desc,fp.created_at desc,fp.id limit least(greatest(page_size,1),30) offset greatest(page_number,0)*least(greatest(page_size,1),30);
$$;
grant execute on function public.get_personalized_feed(integer,integer) to anon,authenticated;
